script:
card({
  name: 'Party RSVP',
  icon: 'party',
  // Each person opens and closes screens on their own. push, pop and
  // go { screen } do it from a button; ctx.push and ctx.pop from an action.
  nav: { each: true },
});

// Opens over the main screen when someone says yes.
screens.food = (state, me) => column([
  text('Anything you don\'t eat?', { bold: true, align: 'center' }),
  row(['Nothing', 'Meat', 'Nuts', 'Dairy'].map((f) => button(f, 'food', { food: f })), { align: 'center' }),
  button('Back', 'pop', null, { tone: 'muted' }),
]);

on.answer = (state, args, ctx) => {
  state.answers[ctx.author] = { name: ctx.authorName, coming: args.coming, food: '' };
  if (args.coming) ctx.push('food');
};

on.food = (state, args, ctx) => {
  if (!state.answers[ctx.author]) throw 'Say if you\'re coming first';
  state.answers[ctx.author].food = args.food;
  ctx.pop();
};

on.change = (state, args, ctx) => {
  delete state.answers[ctx.author];
};

function init(ctx) {
  return { answers: {} };
}

function view(state, me, now, local) {
  // The host, who sent the card, sees everyone's answers and what
  // they don't eat. Guests see the question, then their own answer.
  const coming = Object.values(state.answers).filter((a) => a.coming);
  if (me.isSender) {
    const cant = Object.values(state.answers).filter((a) => !a.coming);
    return column([
      text(coming.length + ' coming', { size: 'large', bold: true, align: 'center' }),
      ...coming.map((a) => row([text(a.name), a.food && a.food !== 'Nothing' ? badge('No ' + a.food.toLowerCase()) : null])),
      cant.length > 0 && text("Can't make it: " + cant.map((a) => a.name).join(', '), { size: 'small', tone: 'muted' }),
    ]);
  }
  const mine = state.answers[me.id];
  if (!mine) {
    return column([
      text('Are you coming?', { size: 'large', bold: true, align: 'center' }),
      row([button('Yes', 'answer', { coming: true }, { tone: 'accent' }), button('No', 'answer', { coming: false })], { align: 'center' }),
    ]);
  }
  return column([
    text(mine.coming ? "You're coming 🎉" : "You can't make it", { size: 'large', bold: true, align: 'center' }),
    text(coming.length + ' coming so far', { size: 'small', tone: 'muted', align: 'center' }),
    button('Change my answer', 'change', null, { tone: 'muted' }),
  ]);
}

function pause(local, ctx) {
  // Runs on this phone when the card leaves the screen.
}

function resume(local, ctx) {
  // Runs on this phone when it comes back.
}
